class Solution {
  public int findMin(int[] nums) {
    int lo = 0, hi = nums.length - 1;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (nums[mid] > nums[hi]) lo = mid + 1;
      else if (nums[mid] < nums[hi]) hi = mid;
      else hi--; // duplicates: nums[hi] is not the only minimum candidate
    }
    return nums[lo];
  }
}
